"""matplotlib.backends.backend_wxcairo — wxcairo backend stub.

The shim renders every figure through plotly, so this module exists to
satisfy ``from matplotlib.backends.backend_wxcairo import
FigureCanvasWxCairo`` imports. Saving uses plotly's native export.
"""

from matplotlib.backends._backend_helpers import (
    _make_canvas, _make_manager, _make_backend,
)


FigureCanvasWxCairo = _make_canvas('FigureCanvasWxCairo', 'png')
FigureManagerWxCairo = _make_manager('FigureManagerWxCairo')

# Aliases — every backend exposes ``FigureCanvas`` and ``FigureManager``.
FigureCanvas = FigureCanvasWxCairo
FigureManager = FigureManagerWxCairo

# Backend class registered with matplotlib's _Backend system.
_BackendStub = _make_backend('_BackendWxCairo', FigureCanvas, FigureManager)
new_figure_manager = _BackendStub.new_figure_manager
draw_if_interactive = _BackendStub.draw_if_interactive
show = _BackendStub.show
